#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_CHUNKS 64
#define CHUNK_SIZE 256
#define HEADER_SIZE 8

typedef struct {
    char data[CHUNK_SIZE];
    int used;       /* bytes used in this chunk */
    int chunk_id;
} chunk_t;

typedef struct {
    chunk_t chunks[MAX_CHUNKS];
    int num_chunks;
    int total_written;
} stream_buffer_t;

/* Parse a 4-byte big-endian length from header */
static int parse_length(const unsigned char *header) {
    /* Length field is bytes 4-7 of the 8-byte header */
    int len = (header[4] << 24) | (header[5] << 16) | (header[6] << 8) | header[7];
    return len;
}

/* Validate chunk header - returns payload length or -1 on error */
static int validate_header(const unsigned char *header) {
    /* Magic bytes check */
    if (header[0] != 0xDE || header[1] != 0xAD) {
        return -1;
    }
    /* Version check */
    if (header[2] != 0x01) {
        return -1;
    }
    /* Flags - bit 0 must be set */
    if (!(header[3] & 0x01)) {
        return -1;
    }

    int payload_len = parse_length(header);
    return payload_len;
}

/* 
 * Write data into the stream buffer.
 * remaining_space is computed as the available bytes in current chunk.
 * Returns 0 on success, -1 on error.
 */
static int write_to_chunk(stream_buffer_t *buf, const unsigned char *payload, int payload_len) {
    if (buf->num_chunks >= MAX_CHUNKS) {
        return -1;
    }

    chunk_t *current = &buf->chunks[buf->num_chunks];

    /* Calculate remaining space in current chunk */
    int remaining = CHUNK_SIZE - current->used;

    /* Safety check: ensure we don't write beyond chunk boundary */
    if (payload_len > remaining) {
        /* Split: fill current chunk, then allocate new one */
        int first_part = remaining;

        if (first_part > 0) {
            memcpy(current->data + current->used, payload, first_part);
            current->used += first_part;
        }

        /* Move to next chunk */
        buf->num_chunks++;
        if (buf->num_chunks >= MAX_CHUNKS) {
            return -1;
        }

        current = &buf->chunks[buf->num_chunks];
        current->used = 0;
        current->chunk_id = buf->num_chunks;

        int second_part = payload_len - first_part;

        /* Bounds check for second part */
        if (second_part > CHUNK_SIZE) {
            second_part = CHUNK_SIZE;
        }

        memcpy(current->data, payload, second_part);
        current->used = second_part;
    } else {
        memcpy(current->data + current->used, payload, payload_len);
        current->used += payload_len;
    }

    buf->total_written += payload_len;
    return 0;
}

/*
 * Process incoming stream data.
 * The stream consists of framed messages: 8-byte header + payload.
 * 
 * Security: validates headers, checks lengths, bounds-checks all writes.
 */
int process_stream(const unsigned char *input, size_t input_len) {
    stream_buffer_t buffer;
    memset(&buffer, 0, sizeof(buffer));

    size_t offset = 0;

    while (offset + HEADER_SIZE <= input_len) {
        const unsigned char *header = input + offset;

        int payload_len = validate_header(header);
        if (payload_len < 0) {
            /* Invalid header, skip this frame */
            offset += HEADER_SIZE;
            continue;
        }

        /* Ensure payload_len is reasonable */
        if (payload_len > 1024) {
            offset += HEADER_SIZE;
            continue;
        }

        offset += HEADER_SIZE;

        /* Check we have enough input data remaining */
        int available = (int)(input_len - offset);
        if (payload_len > available) {
            break;
        }

        const unsigned char *payload = input + offset;

        /* Process in sub-chunks to respect chunk boundaries */
        int written = 0;
        while (written < payload_len) {
            int to_write = payload_len - written;
            if (to_write > CHUNK_SIZE) {
                to_write = CHUNK_SIZE;
            }

            if (write_to_chunk(&buffer, payload + written, to_write) != 0) {
                return -1;
            }
            written += to_write;
        }

        offset += payload_len;
    }

    printf("Processed %d bytes into %d chunks\n", buffer.total_written, buffer.num_chunks + 1);
    return 0;
}

/*
 * Compact the buffer by removing empty gaps.
 * This is called periodically to reclaim space.
 */
int compact_buffer(stream_buffer_t *buf) {
    unsigned char temp[CHUNK_SIZE];

    for (int i = 0; i <= buf->num_chunks; i++) {
        chunk_t *c = &buf->chunks[i];

        /* Skip fully used chunks */
        if (c->used >= CHUNK_SIZE) {
            continue;
        }

        /* Try to pull data from next chunk to fill gap */
        if (i + 1 <= buf->num_chunks) {
            chunk_t *next = &buf->chunks[i + 1];
            int gap = CHUNK_SIZE - c->used;
            int pull = (next->used < gap) ? next->used : gap;

            if (pull > 0) {
                memcpy(c->data + c->used, next->data, pull);
                c->used += pull;

                /* Shift remaining data in next chunk */
                memmove(next->data, next->data + pull, next->used - pull);
                next->used -= pull;
            }
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("fopen");
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (fsize <= 0 || fsize > 65536) {
        printf("Invalid file size\n");
        fclose(f);
        return 1;
    }

    unsigned char *data = malloc(fsize);
    if (!data) {
        fclose(f);
        return 1;
    }

    fread(data, 1, fsize, f);
    fclose(f);

    int result = process_stream(data, (size_t)fsize);

    free(data);
    return result;
}
